#ifndef FB_BATCH_API_H
#define FB_BATCH_API_H
#include "common.h"
typedef struct fb_opaque_batch fb_opaque_batch;
typedef struct fb_batch_stats {
    uint64_t accepted_commands,submitted_pixels,copied_pixels,copied_spans;
    uint64_t row_command_checks,interval_comparisons,flushes;
} fb_batch_stats;
/* Explicit final-frame batching. Until end: source pixels must stay unchanged
 * and alive, and no other drawing/read/update may observe or modify DRAW_BUF.
 * Only RGB_8880 accepted. Returns 0 for invalid input without queueing it.
 * Queues are bounded and can flush early; intermediate results are unspecified.
 */
fb_opaque_batch *fb_opaque_batch_begin(void);
int fb_opaque_batch_add(fb_opaque_batch *,int x,int y,const fb_image *image);
void fb_opaque_batch_end(fb_opaque_batch *,fb_batch_stats *stats);
#endif

/* Exact BGRA row kernels. ARM SIMD is optional; scalar output is the oracle. */
#ifndef FB_FAST_PIXELS_H
#define FB_FAST_PIXELS_H
#include <stdint.h>
#include <string.h>
#if defined(FB_TEST_NEON) || (defined(__aarch64__) && !defined(FB_DISABLE_NEON))
#include <arm_neon.h>
#define FB_HAVE_NEON 1
#else
#define FB_HAVE_NEON 0
#endif
static inline unsigned fb_mix(unsigned s, unsigned d, unsigned a)
{
    unsigned t=s*a+d*(255-a)+128;
    return (t+(t>>8))>>8;
}
static inline uint32_t fb_mix_pixel(uint32_t old, const unsigned char *src, unsigned a, uint32_t ink)
{
    if(!a) return old;
    unsigned b=src?src[0]:ink&255;
    unsigned g=src?src[1]:(ink>>8)&255;
    unsigned r=src?src[2]:(ink>>16)&255;
    if(a!=255) {b=fb_mix(b,old&255,a);g=fb_mix(g,(old>>8)&255,a);r=fb_mix(r,(old>>16)&255,a);}
    return UINT32_C(0xff000000)|(r<<16)|(g<<8)|b;
}
#if FB_HAVE_NEON
static inline uint8x8_t fb_mix8(uint8x8_t s, uint8x8_t d, uint8x8_t a)
{
    uint16x8_t t=vmull_u8(s,a);
    t=vmlal_u8(t,d,vsub_u8(vdup_n_u8(255),a));
    t=vaddq_u16(t,vdupq_n_u16(128));
    t=vaddq_u16(t,vshrq_n_u16(t,8));
    return vshrn_n_u16(t,8);
}
static inline void fb_blend8(unsigned char *dst, uint8x8x4_t s, uint8x8_t a)
{
    uint8x8x4_t d=vld4_u8(dst),out;
    uint8x8_t zero=vceq_u8(a,vdup_n_u8(0));
    for(int k=0;k<3;++k) out.val[k]=vbsl_u8(zero,d.val[k],fb_mix8(s.val[k],d.val[k],a));
    out.val[3]=vbsl_u8(zero,d.val[3],vdup_n_u8(255));
    vst4_u8(dst,out);
}
#endif
static inline void fb_rgba_row(uint32_t *dst,const unsigned char *src,int w)
{
    int x=0;
#if FB_HAVE_NEON
    for(;x+8<=w;x+=8) {
        uint8x8x4_t s=vld4_u8(src+x*4);
        uint64_t bits=vget_lane_u64(vreinterpret_u64_u8(s.val[3]),0);
        if(!bits) continue;
        if(bits==UINT64_MAX) {memcpy(dst+x,src+x*4,32);continue;}
        fb_blend8((unsigned char *)(dst+x),s,s.val[3]);
    }
#endif
    for(;x<w;++x) {
        unsigned a=src[x*4+3];
        if(a) dst[x]=fb_mix_pixel(dst[x],src+x*4,a,0);
    }
}
static inline void fb_alpha_row(uint32_t *dst,const unsigned char *src,int w,uint32_t ink)
{
    int x=0;
#if FB_HAVE_NEON
    uint8x8x4_t s;
    s.val[0]=vdup_n_u8(ink&255);s.val[1]=vdup_n_u8((ink>>8)&255);
    s.val[2]=vdup_n_u8((ink>>16)&255);s.val[3]=vdup_n_u8(255);
    for(;x+8<=w;x+=8) {
        uint8x8_t a=vld1_u8(src+x);
        uint64_t bits=vget_lane_u64(vreinterpret_u64_u8(a),0);
        if(!bits) continue;
        if(bits==UINT64_MAX) {vst4_u8((unsigned char *)(dst+x),s);continue;}
        fb_blend8((unsigned char *)(dst+x),s,a);
    }
#endif
    for(;x<w;++x) if(src[x]) dst[x]=fb_mix_pixel(dst[x],NULL,src[x],ink);
}
static inline void fb_fast_row(uint32_t *dst,const unsigned char *src,int w,int type,uint32_t ink)
{
    if(type==1) memcpy(dst,src,(size_t)w*4);
    else if(type==2) fb_rgba_row(dst,src,w);
    else fb_alpha_row(dst,src,w,ink);
}
#endif

#include "common.h"
#include <sys/ioctl.h>
#include <linux/fb.h>
#include <linux/kd.h>
#include <linux/vt.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>
#include <sys/mman.h>
#include <string.h>

static int LCD_FB_FD;
static int *LCD_FB_BUF;
static int LCD_FB_LINELEN;
static int DRAW_BUF[SCREEN_WIDTH*SCREEN_HEIGHT];

static struct area {
	int x1, x2, y1, y2;
} update_area = {0,0,0,0};

#define AREA_SET_EMPTY(pa) do {\
	(pa)->x1 = SCREEN_WIDTH;\
	(pa)->x2 = 0;\
	(pa)->y1 = SCREEN_HEIGHT;\
	(pa)->y2 = 0;\
} while(0)

void fb_init(char *dev)
{
	int fd;
	struct fb_fix_screeninfo fb_fix;
	struct fb_var_screeninfo fb_var;

	if(LCD_FB_BUF != NULL) return; /*already done*/

	//进入终端图形模式
	fd = open("/dev/tty0",O_RDWR,0);
	ioctl(fd, KDSETMODE, KD_GRAPHICS);
	close(fd);

	//First: Open the device
	if((fd = open(dev, O_RDWR)) < 0){
		printf("Unable to open framebuffer %s, errno = %d\n", dev, errno);
		return;
	}
	if(ioctl(fd, FBIOGET_FSCREENINFO, &fb_fix) < 0){
		printf("Unable to FBIOGET_FSCREENINFO %s\n", dev);
		return;
	}
	if(ioctl(fd, FBIOGET_VSCREENINFO, &fb_var) < 0){
		printf("Unable to FBIOGET_VSCREENINFO %s\n", dev);
		return;
	}

	printf("framebuffer info: bits_per_pixel=%u,size=(%d,%d),virtual_pos_size=(%d,%d)(%d,%d),line_length=%u,smem_len=%u\n",
		fb_var.bits_per_pixel, fb_var.xres, fb_var.yres, fb_var.xoffset, fb_var.yoffset,
		fb_var.xres_virtual, fb_var.yres_virtual, fb_fix.line_length, fb_fix.smem_len);

	//Second: mmap
	void *addr = mmap(NULL, fb_fix.smem_len, PROT_READ|PROT_WRITE, MAP_SHARED, fd, 0);
	if(addr == (void *)-1){
		printf("failed to mmap memory for framebuffer.\n");
		return;
	}

	if((fb_var.xoffset != 0)||(fb_var.yoffset != 0))
	{
		fb_var.xoffset = 0;
		fb_var.yoffset = 0;
		if(ioctl(fd, FBIOPAN_DISPLAY, &fb_var) < 0) {
			printf("FBIOPAN_DISPLAY framebuffer failed\n");
		}
	}

	LCD_FB_FD = fd;
	LCD_FB_BUF = addr;
	LCD_FB_LINELEN = fb_fix.line_length;

	//set empty
	AREA_SET_EMPTY(&update_area);
	return;
}

static void _copy_area(int *dst, int *src, struct area *pa)
{
	int x, y, w, h;
	x = pa->x1; w = pa->x2-x;
	y = pa->y1; h = pa->y2-y;
	char *psrc = (char *)src + y*(SCREEN_WIDTH*4) + x*4;
	char *pdst = (char *)dst + y*LCD_FB_LINELEN + x*4;
	while(h-- > 0){
		memcpy(pdst, psrc, w*4);
		psrc += SCREEN_WIDTH*4;
		pdst += LCD_FB_LINELEN;
	}
}

static int _check_area(struct area *pa)
{
	if(pa->x2 == 0) return 0; //is empty

	if(pa->x1 < 0) pa->x1 = 0;
	if(pa->x2 > SCREEN_WIDTH) pa->x2 = SCREEN_WIDTH;
	if(pa->y1 < 0) pa->y1 = 0;
	if(pa->y2 > SCREEN_HEIGHT) pa->y2 = SCREEN_HEIGHT;

	if((pa->x2 > pa->x1) && (pa->y2 > pa->y1))
		return 1; //no empty

	//set empty
	AREA_SET_EMPTY(pa);
	return 0;
}

void fb_update(void)
{
	if(_check_area(&update_area) == 0) return; //is empty
	_copy_area(LCD_FB_BUF, DRAW_BUF, &update_area);
	AREA_SET_EMPTY(&update_area); //set empty
	return;
}

/*======================================================================*/

static void * _begin_draw(int x, int y, int w, int h)
{
	int x2 = x+w;
	int y2 = y+h;
	if(update_area.x1 > x) update_area.x1 = x;
	if(update_area.y1 > y) update_area.y1 = y;
	if(update_area.x2 < x2) update_area.x2 = x2;
	if(update_area.y2 < y2) update_area.y2 = y2;
	return DRAW_BUF;
}

void fb_draw_pixel(int x, int y, int color)
{
	if(x<0 || y<0 || x>=SCREEN_WIDTH || y>=SCREEN_HEIGHT) return;
	int *buf = _begin_draw(x,y,1,1);
/*---------------------------------------------------*/
	*(buf + y*SCREEN_WIDTH + x) = color;
/*---------------------------------------------------*/
	return;
}

void fb_draw_rect(int x, int y, int w, int h, int color)
{
    if(w <= 0 || h <= 0) return;

    /* Clip before indexing. Widen the sums to avoid signed-int overflow. */
    int64_t left = x;
    int64_t top = y;
    int64_t right = (int64_t)x + w;
    int64_t bottom = (int64_t)y + h;

    if(left < 0) left = 0;
    if(top < 0) top = 0;
    if(right > SCREEN_WIDTH) right = SCREEN_WIDTH;
    if(bottom > SCREEN_HEIGHT) bottom = SCREEN_HEIGHT;
    if(left >= right || top >= bottom) return;

    x = (int)left;
    y = (int)top;
    w = (int)(right - left);
    h = (int)(bottom - top);
    int *buf = _begin_draw(x, y, w, h);

    for(int row = y; row < y + h; ++row) {
        int *pixel = buf + row * SCREEN_WIDTH + x;
        for(int column = 0; column < w; ++column) {
            pixel[column] = color;
        }
    }
    return;
}

void fb_draw_line(int x1, int y1, int x2, int y2, int color)
{
    int64_t dx = (int64_t)x2 - x1;
    int64_t dy = (int64_t)y2 - y1;
    int steep = llabs(dy) > llabs(dx);

    /* Use the longer axis, ordered consistently for reversed endpoints. */
    int64_t major1 = steep ? y1 : x1;
    int64_t major2 = steep ? y2 : x2;
    int64_t minor1 = steep ? x1 : y1;
    int64_t minor2 = steep ? x2 : y2;
    if(major1 > major2) {
        int64_t temporary = major1;
        major1 = major2;
        major2 = temporary;
        temporary = minor1;
        minor1 = minor2;
        minor2 = temporary;
    }

    uint64_t length = (uint64_t)(major2 - major1);
    if(length == 0) {
        fb_draw_pixel(x1, y1, color);
        return;
    }

    int direction = minor2 < minor1 ? -1 : 1;
    uint64_t minor_distance = (uint64_t)llabs(minor2 - minor1);
    int64_t limit = steep ? SCREEN_HEIGHT : SCREEN_WIDTH;
    int64_t first = major1 < 0 ? 0 : major1;
    int64_t last = major2 >= limit ? limit - 1 : major2;
    if(first > last) return;

    /*
     * Integer error accumulation, rounded to the nearest pixel.
     * Preserve the error phase when skipping off-screen major coordinates.
     * For 32-bit int endpoints, this product and sum fit in uint64_t.
     * The loop visits at most SCREEN_WIDTH or SCREEN_HEIGHT coordinates.
     */
    uint64_t numerator = minor_distance * (uint64_t)(first - major1)
                       + length / 2;
    int64_t minor = minor1 + direction * (int64_t)(numerator / length);
    uint64_t remainder = numerator % length;

    for(int64_t major = first; major <= last; ++major) {
        if(steep) {
            fb_draw_pixel((int)minor, (int)major, color);
        } else {
            fb_draw_pixel((int)major, (int)minor, color);
        }
        remainder += minor_distance;
        if(remainder >= length) {
            remainder -= length;
            minor += direction;
        }
    }
    return;
}

/* Blend one channel over an opaque framebuffer, with exact 0/255 endpoints. */
static unsigned blend_channel(unsigned src, unsigned dst, unsigned alpha)
{
    return (src * alpha + dst * (255-alpha) + 127) / 255;
}

void fb_draw_image(int x, int y, fb_image *image, int color)
{
    if(!image || !image->content || image->pixel_w <= 0 || image->pixel_h <= 0) return;
    int bytes = image->color_type == FB_COLOR_ALPHA_8 ? 1 : 4;
    if(image->color_type != FB_COLOR_RGB_8880 &&
       image->color_type != FB_COLOR_RGBA_8888 &&
       image->color_type != FB_COLOR_ALPHA_8) return;
    if(image->line_byte <= 0 || (int64_t)image->pixel_w * bytes > image->line_byte) return;

    int64_t left = x, top = y;
    int64_t right = (int64_t)x + image->pixel_w;
    int64_t bottom = (int64_t)y + image->pixel_h;
    if(left < 0) left = 0;
    if(top < 0) top = 0;
    if(right > SCREEN_WIDTH) right = SCREEN_WIDTH;
    if(bottom > SCREEN_HEIGHT) bottom = SCREEN_HEIGHT;
    if(left >= right || top >= bottom) return;
    int ix = (int)(left-x), iy = (int)(top-y);
    int w = (int)(right-left), h = (int)(bottom-top);
    int *buf = _begin_draw((int)left, (int)top, w, h);
    const unsigned char *source = (const unsigned char *)image->content
        + (size_t)iy * image->line_byte + (size_t)ix * bytes;
    uint32_t foreground = (uint32_t)color;

    for(int row = 0; row < h; ++row) {
        uint32_t *dst = (uint32_t *)(buf + ((int)top+row)*SCREEN_WIDTH + (int)left);
        const unsigned char *src = source + (size_t)row * image->line_byte;
        if(image->color_type == FB_COLOR_RGB_8880) {
            memcpy(dst, src, (size_t)w * 4);
            continue;
        }
        for(int column = 0; column < w; ++column) {
            unsigned alpha, b, g, r;
            if(bytes == 1) {
                alpha = src[column];
                b = foreground & 255; g = (foreground >> 8) & 255; r = (foreground >> 16) & 255;
            } else {
                const unsigned char *p = src + column*4;
                b = p[0]; g = p[1]; r = p[2]; alpha = p[3];
            }
            if(alpha == 0) continue;
            if(alpha != 255) {
                uint32_t old = dst[column];
                b = blend_channel(b, old & 255, alpha);
                g = blend_channel(g, (old >> 8) & 255, alpha);
                r = blend_channel(r, (old >> 16) & 255, alpha);
            }
            dst[column] = UINT32_C(0xff000000) | (r << 16) | (g << 8) | b;
        }
    }
}

void fb_draw_border(int x, int y, int w, int h, int color)
{
	if(w<=0 || h<=0) return;
	fb_draw_rect(x, y, w, 1, color);
	if(h > 1) {
		fb_draw_rect(x, y+h-1, w, 1, color);
		fb_draw_rect(x, y+1, 1, h-2, color);
		if(w > 1) fb_draw_rect(x+w-1, y+1, 1, h-2, color);
	}
}

/** draw a text string **/
void fb_draw_text(int x, int y, char *text, int font_size, int color)
{
	fb_image *img;
	fb_font_info info;
	int i=0;
	int len = strlen(text);
	while(i < len)
	{
		img = fb_read_font_image(text+i, font_size, &info);
		if(img == NULL) break;
		fb_draw_image(x+info.left, y-info.top, img, color);
		fb_free_image(img);

		x += info.advance_x;
		i += info.bytes;
	}
	return;
}

