    uint32_t foreground = (uint32_t)color;

    /* Workers own disjoint destination rows; dirty box set before launch.
     * Implicit end barrier preserves immediate drawing and timing semantics. */
    #ifndef FB_PARALLEL_MIN_PIXELS
    #define FB_PARALLEL_MIN_PIXELS 65536
    #endif
    #ifdef _OPENMP
    #pragma omp parallel for schedule(static) if((size_t)w * h >= FB_PARALLEL_MIN_PIXELS)
    #endif
    for(int row = 0; row < h; ++row) {
        uint32_t *dst = (uint32_t *)(buf + ((int)top+row)*SCREEN_WIDTH + (int)left);
        const unsigned char *src = source + (size_t)row * image->line_byte;
        if(image->color_type == FB_COLOR_RGB_8880) {
