void font_init(char *font_file)
{
	FT_Error error;

	if(library == NULL)
	{
		error = FT_Init_FreeType(&library);
		if(error){
			printf("FT_Init_FreeType: error %d\n",error);
			library = NULL;
			return;
		}
	}
	if(face == NULL)
	{
		error = FT_New_Face(library, font_file, 0, &face);
		if(error){
			printf("FT_New_Face(\"%s\"): error %d\n", font_file, error);
			face = NULL;
			return;
		}
		error = FT_Select_Charmap(face, FT_ENCODING_UNICODE);
		if(error){
			printf("FT_Select_Charmap: error %d\n",error);
			face = NULL;
			return;
		}
	}
	return;
}

/** read a font image **/ 
fb_image* fb_read_font_image(const char *text, int pixel_size, fb_font_info *info)
{
	if(face == NULL) {
		printf("call font_init(\"font_file\") first\n");
		return NULL;
	}
	if((text == NULL)||(pixel_size <= 0)) {
		printf("arg error\n");
		return NULL;
	}

	fb_font_info sinfo;
	FT_ULong ucs4;
	if((text[0]&0x80) == 0){
		sinfo.bytes = 1;
		ucs4 = (unsigned char)text[0];
	}else if((text[0]&0xE0) == 0xC0){
		sinfo.bytes = 2;
		ucs4 = ((text[0]&0x1F)<<6)|(text[1]&0x3F);
	}else if((text[0]&0xF0) == 0xE0){
		sinfo.bytes = 3;
		ucs4 = ((text[0]&0x0F)<<12)|((text[1]&0x3F)<<6)|(text[2]&0x3F);
	}else if((text[0]&0xF8) == 0xF0){
		sinfo.bytes = 4;
		ucs4 = ((text[0]&0x07)<<18)|((text[1]&0x3F)<<12)|((text[2]&0x3F)<<6)|(text[3]&0x3F);
	}else{
		printf("code error!\n");
		return NULL;
	}

	for(unsigned entry = 0; entry < GLYPH_CACHE_COUNT; ++entry) {
		struct glyph_cache_entry *cached = &glyph_cache[entry];
		if(cached->image && cached->face == face &&
		   cached->codepoint == ucs4 && cached->pixel_size == pixel_size) {
			fb_image *copy = copy_glyph_image(cached->image);
			if(copy) {
				if(info) { *info = cached->info; info->bytes = sinfo.bytes; }
				return copy;
			}
			break;
		}
	}

	FT_Error error = FT_Set_Pixel_Sizes(face, 0, pixel_size);
	if(error){
		printf("FT_Set_Pixel_Sizes: error %d\n", error);
		return NULL;
	}
	error = FT_Load_Char(face, ucs4, FT_LOAD_RENDER);
	if(error){
		printf("FT_Load_Char: error %d", error);
		return NULL;
	}
	FT_GlyphSlot slot = face->glyph;

	fb_image* image;
	/*when ucs4 == 0x20 (blank), the bitmap.width/rows/pitch is 0*/
	image = fb_new_image(FB_COLOR_ALPHA_8, slot->bitmap.width, slot->bitmap.rows, slot->bitmap.pitch);
	if(image == NULL){
		printf("fb_new_image(\"%s\", %d,%d,%d) failed\n", text, slot->bitmap.width, slot->bitmap.rows, slot->bitmap.pitch);
		return NULL;
	}
	if(slot->bitmap.rows && slot->bitmap.pitch > 0)
		memcpy(image->content, slot->bitmap.buffer, (size_t)slot->bitmap.rows * slot->bitmap.pitch);

	sinfo.advance_x = slot->advance.x >> 6;
	sinfo.left = slot->bitmap_left;
	sinfo.top = slot->bitmap_top;
	if(info) *info = sinfo;
	if((size_t)image->pixel_h * image->line_byte <= GLYPH_CACHE_MAX_BYTES) {
		fb_image *copy = copy_glyph_image(image);
		if(copy) {
			struct glyph_cache_entry *cached = &glyph_cache[glyph_cache_next];
			fb_free_image(cached->image);
			*cached = (struct glyph_cache_entry){face, ucs4, pixel_size, sinfo, copy};
			glyph_cache_next = (glyph_cache_next + 1) % GLYPH_CACHE_COUNT;
		}
	}
	return image;
}


/* Identity for layout-cache keys. Images returned by the existing API stay owned. */
const void *fb_font_identity(void) { return face; }

/* Cache rendered glyphs for any text/size. Returned images remain caller-owned.
 * Round-robin eviction bounds retained bitmap data to 64 * 64 KiB.
 * Failed cache allocations simply fall back to normal FreeType rendering.
 */
#define GLYPH_CACHE_COUNT 64
#define GLYPH_CACHE_MAX_BYTES (64U * 1024U)
static struct glyph_cache_entry {
	FT_Face face;
	FT_ULong codepoint;
	int pixel_size;
	fb_font_info info;
	fb_image *image;
} glyph_cache[GLYPH_CACHE_COUNT];
static unsigned glyph_cache_next;

static fb_image *copy_glyph_image(const fb_image *source)
{
	fb_image *copy = fb_new_image(source->color_type, source->pixel_w,
		source->pixel_h, source->line_byte);
	if(copy && source->pixel_h && source->line_byte)
		memcpy(copy->content, source->content,
			(size_t)source->pixel_h * source->line_byte);
	return copy;
}

for(unsigned entry = 0; entry < GLYPH_CACHE_COUNT; ++entry) {
	struct glyph_cache_entry *cached = &glyph_cache[entry];
	if(cached->image && cached->face == face &&
	   cached->codepoint == ucs4 && cached->pixel_size == pixel_size) {
		fb_image *copy = copy_glyph_image(cached->image);
		if(copy) {
			if(info) { *info = cached->info; info->bytes = sinfo.bytes; }
			return copy;
		}
		break;
	}
}

FT_Error error = FT_Set_Pixel_Sizes(face, 0, pixel_size);
if(error){
	printf("FT_Set_Pixel_Sizes: error %d\n", error);
	return NULL;
}

if((size_t)image->pixel_h * image->line_byte <= GLYPH_CACHE_MAX_BYTES) {
	fb_image *copy = copy_glyph_image(image);
	if(copy) {
		struct glyph_cache_entry *cached = &glyph_cache[glyph_cache_next];
		fb_free_image(cached->image);
		*cached = (struct glyph_cache_entry){face, ucs4, pixel_size, sinfo, copy};
		glyph_cache_next = (glyph_cache_next + 1) % GLYPH_CACHE_COUNT;
	}
}

/* Private implementation: reverse opaque coverage, independent target rows. */
#include "batch_api.h"
#ifndef FB_BATCH_CAPACITY
#define FB_BATCH_CAPACITY 256
#endif
struct fb_batch_command {
    int left,right,top,bottom,stride;
    const unsigned char *source;
};
struct fb_opaque_batch {
    unsigned count;
    struct fb_batch_command commands[FB_BATCH_CAPACITY];
    fb_batch_stats stats;
};
struct fb_covered_span {int left,right;};
struct fb_row_stats {uint64_t writes,spans,checks,comparisons;};
static struct fb_row_stats fb_batch_row(const fb_opaque_batch *batch,int y)
{
    /* At most ceil(width/2) non-adjacent nonempty integer intervals exist. */
    struct fb_covered_span covered[(SCREEN_WIDTH+1)/2+1];
    int count=0;
    struct fb_row_stats result={0};
    for(unsigned command=batch->count;command>0;--command) {
        const struct fb_batch_command *c=&batch->commands[command-1];
        result.checks++;
        if(y<c->top || y>=c->bottom)continue;
        int cursor=c->left;
        const unsigned char *row=c->source+(size_t)(y-c->top)*c->stride;
        for(int i=0;i<count && covered[i].left<c->right;++i) {
            result.comparisons++;
            if(covered[i].right<=cursor)continue;
            if(covered[i].left>cursor) {
                int end=covered[i].left<c->right?covered[i].left:c->right;
                memcpy(DRAW_BUF+y*SCREEN_WIDTH+cursor,row+(size_t)(cursor-c->left)*4,(size_t)(end-cursor)*4);
                result.writes+=(unsigned)(end-cursor);result.spans++;
            }
            if(cursor<covered[i].right)cursor=covered[i].right;
            if(cursor>=c->right)break;
        }
        if(cursor<c->right) {
            memcpy(DRAW_BUF+y*SCREEN_WIDTH+cursor,row+(size_t)(cursor-c->left)*4,(size_t)(c->right-cursor)*4);
            result.writes+=(unsigned)(c->right-cursor);result.spans++;
        }
        /* Union this rectangle's row with existing sorted, disjoint coverage. */
        int first=0,left=c->left,right=c->right;
        while(first<count && covered[first].right<left){first++;result.comparisons++;}
        int last=first;
        while(last<count && covered[last].left<=right) {
            if(left>covered[last].left)left=covered[last].left;
            if(right<covered[last].right)right=covered[last].right;
            last++;result.comparisons++;
        }
        memmove(covered+first+1,covered+last,(size_t)(count-last)*sizeof(*covered));
        count=count-(last-first)+1;covered[first]=(struct fb_covered_span){left,right};
        if(count==1 && left==0 && right==SCREEN_WIDTH)break;
    }
    return result;
}
static void fb_batch_flush(fb_opaque_batch *batch)
{
    if(!batch->count)return;
    int left=SCREEN_WIDTH,right=0,top=SCREEN_HEIGHT,bottom=0;
    for(unsigned i=0;i<batch->count;i++) {
        const struct fb_batch_command *c=&batch->commands[i];
        if(left>c->left)left=c->left;
        if(right<c->right)right=c->right;
        if(top>c->top)top=c->top;
        if(bottom<c->bottom)bottom=c->bottom;
    }
    _begin_draw(left,top,right-left,bottom-top);
    uint64_t writes=0,spans=0,checks=0,comparisons=0;
    #ifdef _OPENMP
    #pragma omp parallel for schedule(static) reduction(+:writes,spans,checks,comparisons) if(batch->count>8 && bottom-top>64)
    #endif
    for(int y=top;y<bottom;y++) {
        struct fb_row_stats row=fb_batch_row(batch,y);
        writes+=row.writes;spans+=row.spans;checks+=row.checks;comparisons+=row.comparisons;
    }
    batch->stats.copied_pixels+=writes;batch->stats.copied_spans+=spans;
    batch->stats.row_command_checks+=checks;batch->stats.interval_comparisons+=comparisons;
    batch->stats.flushes++;batch->count=0;
}
fb_opaque_batch *fb_opaque_batch_begin(void){return calloc(1,sizeof(fb_opaque_batch));}
int fb_opaque_batch_add(fb_opaque_batch *batch,int x,int y,const fb_image *image)
{
    if(!batch || !image || !image->content || image->color_type!=FB_COLOR_RGB_8880 ||
       image->pixel_w<=0 || image->pixel_h<=0 || image->line_byte<=0 ||
       (int64_t)image->pixel_w*4>image->line_byte)return 0;
    batch->stats.accepted_commands++;
    int64_t left=x,top=y,right=(int64_t)x+image->pixel_w,bottom=(int64_t)y+image->pixel_h;
    if(left<0)left=0;
    if(top<0)top=0;
    if(right>SCREEN_WIDTH)right=SCREEN_WIDTH;
    if(bottom>SCREEN_HEIGHT)bottom=SCREEN_HEIGHT;
    if(left>=right || top>=bottom)return 1;
    if(batch->count==FB_BATCH_CAPACITY)fb_batch_flush(batch);
    batch->commands[batch->count++]=(struct fb_batch_command){(int)left,(int)right,(int)top,(int)bottom,image->line_byte,
        (const unsigned char *)image->content+(size_t)(top-y)*image->line_byte+(size_t)(left-x)*4};
    batch->stats.submitted_pixels+=(uint64_t)(right-left)*(bottom-top);
    return 1;
}
void fb_opaque_batch_end(fb_opaque_batch *batch,fb_batch_stats *stats)
{
    if(!batch){if(stats)memset(stats,0,sizeof(*stats));return;}
    fb_batch_flush(batch);if(stats)*stats=batch->stats;free(batch);
}

/* Bounded layout cache; keeps separate owned glyphs and preserves draw order. */
#ifndef FB_TEXT_LAYOUT_H
#define FB_TEXT_LAYOUT_H
const void *fb_font_identity(void);
#define FB_LAYOUT_SLOTS 8
#define FB_LAYOUT_GLYPHS 128
#define FB_LAYOUT_TEXT_BYTES 256
#define FB_LAYOUT_MAX_BYTES (64U*1024U)
struct fb_layout_glyph {fb_image *image;fb_font_info info;int offset;};
struct fb_layout_entry {
    const void *font;
    int size,count;
    char text[FB_LAYOUT_TEXT_BYTES+1];
    struct fb_layout_glyph *glyphs;
};
static struct fb_layout_entry fb_layouts[FB_LAYOUT_SLOTS];
static unsigned fb_layout_next;
static int fb_layout_cleanup_registered;
static void fb_layout_release(struct fb_layout_entry *entry)
{
    for(int i=0;i<entry->count;++i) fb_free_image(entry->glyphs[i].image);
    free(entry->glyphs);
    memset(entry,0,sizeof(*entry));
}
static void fb_layout_cleanup(void)
{
    for(int i=0;i<FB_LAYOUT_SLOTS;++i) fb_layout_release(&fb_layouts[i]);
}
static struct fb_layout_entry *fb_layout_get(const char *text,int size)
{
    const void *font=fb_font_identity();
    if(!font || size<=0 || size>128) return NULL;
    size_t length=strlen(text);
    if(!length || length>FB_LAYOUT_TEXT_BYTES) return NULL;
    for(int i=0;i<FB_LAYOUT_SLOTS;++i) {
        struct fb_layout_entry *e=&fb_layouts[i];
        if(e->glyphs && e->font==font && e->size==size && !strcmp(e->text,text)) return e;
    }
    struct fb_layout_entry e={0};
    e.glyphs=calloc(FB_LAYOUT_GLYPHS,sizeof(*e.glyphs));
    if(!e.glyphs) return NULL;
    e.font=font;e.size=size;memcpy(e.text,text,length+1);
    size_t index=0,total_bytes=0;
    int64_t advance=0;
    while(index<length && e.count<FB_LAYOUT_GLYPHS) {
        fb_font_info info={0};
        fb_image *image=fb_read_font_image(text+index,size,&info);
        if(!image || info.bytes<=0 || (size_t)info.bytes>length-index) {
            fb_free_image(image);fb_layout_release(&e);return NULL;
        }
        size_t bytes=(size_t)image->line_byte*image->pixel_h;
        if(bytes>FB_LAYOUT_MAX_BYTES-total_bytes || advance<INT_MIN || advance>INT_MAX) {
            fb_free_image(image);fb_layout_release(&e);return NULL;
        }
        e.glyphs[e.count++]=(struct fb_layout_glyph){image,info,(int)advance};
        total_bytes+=bytes;index+=(size_t)info.bytes;advance+=info.advance_x;
    }
    if(index!=length) {fb_layout_release(&e);return NULL;}
    if(!fb_layout_cleanup_registered) {
        if(atexit(fb_layout_cleanup)) {fb_layout_release(&e);return NULL;}
        fb_layout_cleanup_registered=1;
    }
    struct fb_layout_entry *slot=&fb_layouts[fb_layout_next];
    fb_layout_release(slot);*slot=e;
    fb_layout_next=(fb_layout_next+1)%FB_LAYOUT_SLOTS;
    return slot;
}
void fb_draw_text(int x,int y,char *text,int font_size,int color)
{
    if(!text) return;
    struct fb_layout_entry *layout=fb_layout_get(text,font_size);
    if(layout) {
        for(int i=0;i<layout->count;++i) {
            const struct fb_layout_glyph *g=&layout->glyphs[i];
            fb_draw_image(x+g->offset+g->info.left,y-g->info.top,g->image,color);
        }
        return;
    }
    size_t i=0,length=strlen(text);
    while(i<length) {
        fb_font_info info={0};
        fb_image *image=fb_read_font_image(text+i,font_size,&info);
        if(!image) break;
        if(info.bytes<=0 || (size_t)info.bytes>length-i) {fb_free_image(image);break;}
        fb_draw_image(x+info.left,y-info.top,image,color);
        fb_free_image(image);x+=info.advance_x;i+=(size_t)info.bytes;
    }
}
#endif

/* Called only after course timers end. Retain all original drawing work. */
#include <stdio.h>
#include <time.h>
#include <stdint.h>
#undef fb_update
void fb_update_impl(void);
void fb_update(void)
{
    struct timespec before, after;
    clock_gettime(CLOCK_MONOTONIC, &before);
    fb_update_impl();
    clock_gettime(CLOCK_MONOTONIC, &after);
    int64_t us = (int64_t)(after.tv_sec-before.tv_sec)*1000000
               + (after.tv_nsec-before.tv_nsec)/1000;
    fprintf(stderr, "FLUSH_US=%lld\n", (long long)us);
}

"""Read-only checks on the Orange Pi. Does not stop the desktop or change Bluetooth."""
from pathlib import Path
import argparse, array, fcntl, json, os, shutil, subprocess, sys

def touchscreen_info(path):
    descriptor=os.open(path,os.O_RDONLY|os.O_NONBLOCK)
    try:
        axes={}
        for name,code in (("slot",0x2f),("x",0x35),("y",0x36)):
            values=array.array("i",[0]*6)
            request=(2<<30)|(24<<16)|(ord("E")<<8)|(0x40+code)
            fcntl.ioctl(descriptor,request,values,True)
            axes[name]={"minimum":values[1],"maximum":values[2]}
        return {"path":str(path),"axes":axes}
    finally:os.close(descriptor)

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project",required=True)
    parser.add_argument("--lab",choices=("lab2","lab3","lab4","lab5_bt","test"),required=True)
    parser.add_argument("--touch");parser.add_argument("--serial",default="/dev/rfcomm0")
    parser.add_argument("--headless",action="store_true")
    args=parser.parse_args();project=Path(args.project).resolve(strict=True)
    failures=[];info={"project":str(project),"lab":args.lab,"checksAreReadOnly":True}
    binary=project/"out"/args.lab
    if not binary.is_file() or not os.access(binary,os.X_OK):failures.append(f"Build executable first: {binary}")
    if not args.headless:
        try:
            descriptor=os.open("/dev/fb0",os.O_RDONLY)
            try:
                values=array.array("I",[0]*40);fcntl.ioctl(descriptor,0x4600,values,True)
            finally:os.close(descriptor)
            info["framebuffer"]={"width":values[0],"height":values[1],"bitsPerPixel":values[6],
                "red":[values[8],values[9]],"green":[values[11],values[12]],"blue":[values[14],values[15]]}
            if (values[0],values[1],values[6],values[8],values[9],values[11],values[12],values[14],values[15])!=(1024,600,32,16,8,8,8,0,8):
                failures.append("Framebuffer format differs from course constants; adjust mode/code before running.")
        except OSError as error:failures.append(f"Framebuffer unavailable: {error}")
        if not os.access("/dev/fb0",os.R_OK|os.W_OK):failures.append("Framebuffer is not readable/writable.")
        for name in ("font.ttc", "test.jpg", "test.png"):
            if args.lab in ("lab3","test") or name=="font.ttc":
                if not (project/"out"/name).is_file():failures.append(f"Missing asset: out/{name}")
        if args.lab in ("lab4","lab5_bt"):
            devices=[]
            for path in ([Path(args.touch)] if args.touch else sorted(Path("/dev/input").glob("event*"))):
                try:devices.append(touchscreen_info(path))
                except OSError:continue
            info["protocolBTouchscreens"]=devices
            if not devices:failures.append("No protocol-B touchscreen detected; check its USB touch cable.")
            if len(devices)>1 and not args.touch:failures.append("Multiple touchscreens; choose --touch /dev/input/eventN explicitly.")
        if shutil.which("systemctl"):
            check=subprocess.run(["systemctl","is-active","display-manager"],capture_output=True,text=True)
